function countOccurrences(text, searchString) {
    let count = 0;
    let index = text.toLowerCase().indexOf(searchString.toLowerCase());

    while (index !== -1) {
        count++;
        index = text.toLowerCase().indexOf(searchString.toLowerCase(), index + 1);
    }

    return count;
}

console.log(countOccurrences("Hello world, hello Universe!", "hello")); // should return 2
console.log(countOccurrences("Case insensitive search", "Search")); // should return 1
```

